
'use client'
import style from './registro.module.css'


import Form from '@/components/ui/forms/formulario'
import Input from '@/components/ui/input/campos'
import Card from '@/components/ui/card/card';
import Select from '@/components/ui/select/selector';
import Img from '@/components/ui/avatar/foto';

import { usuarioPayload, usuarioSchema } from '@/schemas/usuarioSchema';
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from 'react-hook-form';

function registro() {
    const options = [
        { label: 'Estudiante', value: 'student' },
        { label: 'Docente', value: 'teacher' },
        { label: 'Directivo', value: 'admin' },
    ];


    const {
        register,
        handleSubmit,
        formState: { errors, isSubmitting },
    } = useForm<usuarioPayload>({
        resolver: zodResolver(usuarioSchema),
    });

    const onSubmitForm = (datos: usuarioPayload) => {
        console.log('Datos enviados:', datos);
    };

    return (
        <Card className={style.card}>
            <Form onSubmit={handleSubmit(onSubmitForm)} columns={4} >
                <div className={style.titulo}>
                    <h1>Registro estudiante</h1>
                </div>


                <h2 className={style.titulo_h2}>Datos Personales</h2>

                <Img src='' />

                <Select
                    label="Tipo de documento"
                    name="tipo"
                    options={options}
                    register={register('tipo', { required: 'Este campo es obligatorio' })}
                    error={errors.doc}
                />

                <Input
                    label="Numero de documento"
                    name="doc"
                    placeholder="Numero de documento"
                    register={register('doc')}
                    error={errors.doc}
                />

                <Input
                    label="Primer nombre"
                    name="n1"
                    placeholder="Primer nombre"
                    register={register('doc')}
                    error={errors.doc}
                />

                <Input
                    label="Segundo nombre"
                    name="n2"
                    placeholder="Segundo nombre"
                    register={register('n2')}
                    error={errors.doc}
                />

                <Input
                    label="Primer apellido"
                    name="ap1"
                    placeholder="Primer apellido"
                    register={register('ap1')}
                    error={errors.doc}
                />

                <Input
                    label="Segundo apellido"
                    name="ap2"
                    placeholder="Primer apellido"
                    register={register('ap2')}
                    error={errors.doc}
                />

                <Input
                    label="Correo electrónico"
                    name="email"
                    type='email'
                    placeholder="Correo electrónico"
                    register={register('email')}
                    error={errors.doc}
                />

                <Input
                    label="Direccion de residencia"
                    name="ubicacion"
                    placeholder="Direccion de residencia"
                    register={register('ubicacion')}
                    error={errors.doc}
                />

                <Input
                    label="Teléfono"
                    name="tel"
                    placeholder="Teléfono"
                    register={register('tel')}
                    error={errors.doc}
                />

                <Input
                    label="Contraseña"
                    name="clave"
                    type='password'
                    placeholder="Contraseña"
                    register={register('clave')}
                    error={errors.doc}
                />

                <Select
                    label="Rol institucional"
                    name="tipo"
                    options={options}
                    register={register('tipo', { required: 'Este campo es obligatorio' })}
                    error={errors.doc}
                />

            </Form>
        </Card>
    )
}

export default registro
